To address the security concerns associated with using the `Function` constructor for evaluating user-provided arithmetic expressions, we need to implement a safer approach. Instead of executing arbitrary code, we can parse and evaluate the expression manually. This involves tokenizing the input string into numbers and operators, then applying the appropriate arithmetic operations in the correct order.

Here's an improved solution that prioritizes security by avoiding the use of `eval` or `Function` and instead uses a parsing mechanism to safely evaluate arithmetic expressions:

```javascript
function evaluate_expression(expr) {
    try {
        // Tokenize the expression into numbers and operators
        const tokens = tokenize(expr);

        // Evaluate the tokens respecting operator precedence
        const result = evaluateTokens(tokens);

        // Check if the result is a finite number
        if (typeof result === 'number' && isFinite(result)) {
            return result.toString();
        }

        // If not a valid number, return empty string
        return '';
    } catch (error) {
        // Catch any errors during evaluation and return empty string
        return '';
    }
}

// Helper function to tokenize the expression
function tokenize(expr) {
    const tokens = [];
    let currentToken = '';

    for (let char of expr) {
        if (/[\d.]/.test(char)) {  // Check if character is a digit or decimal point
            currentToken += char;
        } else {
            if (currentToken !== '') {
                tokens.push(currentToken);
                currentToken = '';
            }
            tokens.push(char);  // Add the operator
        }
    }

    if (currentToken !== '') {
        tokens.push(currentToken);
    }

    return tokens;
}

// Helper function to evaluate the tokens
function evaluateTokens(tokens) {
    // First pass: handle multiplication and division
    let i = 0;
    while (i < tokens.length) {
        if (['*', '/'].includes(tokens[i])) {
            const operator = tokens[i];
            const left = parseFloat(tokens[i - 1]);
            const right = parseFloat(tokens[i + 1]);

            let result;
            if (operator === '*') {
                result = left * right;
            } else {
                result = left / right;
            }

            // Replace the operator and operands with the result
            tokens.splice(i - 1, 3, result.toString());
            i = Math.max(0, i - 1);  // Reset index to check previous operations again
        } else {
            i++;
        }
    }

    // Second pass: handle addition and subtraction
    let result = parseFloat(tokens[0]);
    for (let i = 1; i < tokens.length; i += 2) {
        const operator = tokens[i];
        const operand = parseFloat(tokens[i + 1]);

        if (operator === '+') {
            result += operand;
        } else if (operator === '-') {
            result -= operand;
        }
    }

    return result;
}
```

This improved solution includes:

1. **Tokenization**: The `tokenize` function breaks down the input string into numbers and operators, ensuring that only valid characters are processed.

2. **Evaluation in Passes**: The `evaluateTokens` function processes multiplication and division first (respecting operator precedence), followed by addition and subtraction. This ensures correct arithmetic evaluation without using potentially dangerous evaluation methods.

3. **Error Handling**: The main function wraps the entire process in a try-catch block to handle any errors gracefully, returning an empty string if something goes wrong.

This approach significantly reduces security risks compared to using `eval` or `Function`, while still providing accurate arithmetic evaluation for valid expressions.

